inline ::flatbuffers::Offset<QEM> CreateQEM(::flatbuffers::FlatBufferBuilder &_fbb, const QEMT *_o, const ::flatbuffers::rehasher_function_t *_rehasher) {
  return QEM::Pack(_fbb, _o, _rehasher);
}

inline ::flatbuffers::Offset<QEM> QEM::Pack(::flatbuffers::FlatBufferBuilder &_fbb, const QEMT* _o, const ::flatbuffers::rehasher_function_t *_rehasher) {
  (void)_rehasher;
  (void)_o;
  struct _VectorArgs { ::flatbuffers::FlatBufferBuilder *__fbb; const QEMT* __o; const ::flatbuffers::rehasher_function_t *__rehasher; } _va = { &_fbb, _o, _rehasher}; (void)_va;
  auto _MODEL_ID = _o->MODEL_ID.empty() ? 0 : _fbb.CreateString(_o->MODEL_ID);
  auto _MODEL_VERSION = _o->MODEL_VERSION.empty() ? 0 : _fbb.CreateString(_o->MODEL_VERSION);
  auto _MODEL_WEIGHTS_SHA256 = _o->MODEL_WEIGHTS_SHA256.empty() ? 0 : _fbb.CreateString(_o->MODEL_WEIGHTS_SHA256);
  auto _POOLING_METHOD = _o->POOLING_METHOD;
  auto _TEMPLATE_VERSION = _o->TEMPLATE_VERSION.empty() ? 0 : _fbb.CreateString(_o->TEMPLATE_VERSION);
  auto _DIMENSIONS = _o->DIMENSIONS;
  auto _ENCODING = _o->ENCODING;
  auto _NORMALIZATION = _o->NORMALIZATION;
  auto _VOCAB_SIZE = _o->VOCAB_SIZE;
  auto _TOKENS = _o->TOKENS.size() ? _fbb.CreateVector<::flatbuffers::Offset<QEMTokenVector>> (_o->TOKENS.size(), [](size_t i, _VectorArgs *__va) { return CreateQEMTokenVector(*__va->__fbb, __va->__o->TOKENS[i].get(), __va->__rehasher); }, &_va ) : 0;
  return CreateQEM(
      _fbb,
      _MODEL_ID,
      _MODEL_VERSION,
      _MODEL_WEIGHTS_SHA256,
      _POOLING_METHOD,
      _TEMPLATE_VERSION,
      _DIMENSIONS,
      _ENCODING,
      _NORMALIZATION,
      _VOCAB_SIZE,
      _TOKENS);
}

inline const QEM *GetQEM(const void *buf) {
  return ::flatbuffers::GetRoot<QEM>(buf);
}

inline const QEM *GetSizePrefixedQEM(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<QEM>(buf);
}

inline const char *QEMIdentifier() {
  return "$QEM";
}

inline bool QEMBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, QEMIdentifier());
}

inline bool SizePrefixedQEMBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, QEMIdentifier(), true);
}

template <bool B = false>
inline bool VerifyQEMBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<QEM>(QEMIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedQEMBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<QEM>(QEMIdentifier());
}

inline void FinishQEMBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<QEM> root) {
  fbb.Finish(root, QEMIdentifier());
}

inline void FinishSizePrefixedQEMBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<QEM> root) {
  fbb.FinishSizePrefixed(root, QEMIdentifier());
}

inline std::unique_ptr<QEMT> UnPackQEM(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<QEMT>(GetQEM(buf)->UnPack(res));
}

inline std::unique_ptr<QEMT> UnPackSizePrefixedQEM(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<QEMT>(GetSizePrefixedQEM(buf)->UnPack(res));
}

